}

fn basic_device_operations() -> Vec<LinuxOperation> {
    vec![
        LinuxOperation::CreateBasicDevice {
            path: "/dev/null".into(),
            major: 1,
            minor: 3,
            mode: 0o666,
        },
        LinuxOperation::CreateBasicDevice {
            path: "/dev/zero".into(),
            major: 1,
            minor: 5,
            mode: 0o666,
        },
        LinuxOperation::CreateBasicDevice {
            path: "/dev/full".into(),
            major: 1,
            minor: 7,
            mode: 0o666,
        },
        LinuxOperation::CreateBasicDevice {
            path: "/dev/random".into(),
            major: 1,
            minor: 8,
            mode: 0o666,
        },
        LinuxOperation::CreateBasicDevice {
            path: "/dev/urandom".into(),
            major: 1,
            minor: 9,
            mode: 0o666,
        },
        LinuxOperation::CreateBasicDevice {
            path: "/dev/fuse".into(),
            major: 10,
            minor: 229,
            mode: 0o666,
        },
