        assert_eq!(construction, CONSTRUCTION_ORDER);
        let teardown: Vec<_> = plan.teardown.iter().map(|entry| entry.step).collect();
        assert_eq!(
            teardown,
            CONSTRUCTION_ORDER.into_iter().rev().collect::<Vec<_>>()
        );
    }

    #[test]
